create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, role text not null default 'user' check(role in ('user','admin')), created_at timestamptz not null default now());
create table public.news (id uuid primary key default gen_random_uuid(), title text not null, summary text, body text, category text not null, image_url text, published boolean not null default false, published_at timestamptz not null default now(), author_id uuid references public.profiles(id));
create table public.favorites (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, entity_type text not null check(entity_type in ('team','player')), entity_id text not null, unique(user_id,entity_type,entity_id));
create table public.bookmarks (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, news_id uuid not null references public.news(id) on delete cascade, unique(user_id,news_id));
create table public.comments (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, news_id uuid not null references public.news(id) on delete cascade, body text not null check(char_length(body) between 1 and 2000), created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.news enable row level security; alter table public.favorites enable row level security; alter table public.bookmarks enable row level security; alter table public.comments enable row level security;
create policy "published news readable" on public.news for select using (published or (select role from public.profiles where id=auth.uid())='admin');
create policy "users manage favorites" on public.favorites for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "users manage bookmarks" on public.bookmarks for all using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "comments readable" on public.comments for select using (true); create policy "users create comments" on public.comments for insert with check(auth.uid()=user_id);
create policy "admins manage news" on public.news for all using ((select role from public.profiles where id=auth.uid())='admin') with check ((select role from public.profiles where id=auth.uid())='admin');
